const date = new Date("2026-10-19T08:00:00.000Z");
export function curatedColoringCards(categorySlug?: string) {
  return CURATED_COLORING_PAGES
    .filter(page => !categorySlug || page.categorySlug === categorySlug)
    .map(page => ({
      id: page.id, title: page.title, slug: page.slug, description: page.description,
      imageUrl: page.imageUrl, svgContent: null as string | null, altText: page.altText,
      categoryId: null as number | null, categoryName: page.categoryName,
      categorySlug: page.categorySlug, ageRange: page.ageRange,
      difficulty: page.difficulty, featured: page.featured, popular: page.popular, publishedAt: date,
    }));
}
export function curatedColoringPage(slug: string, categorySlug?: string) {
  const page = CURATED_COLORING_PAGES.find(page => page.slug === slug && (!categorySlug || page.categorySlug === categorySlug));
  if (!page) return null;
  return {
    ...page, categoryId: null as number | null, svgUrl: page.imageUrl,
    seoTitle: page.title + " | CraftColoring",
    seoDescription: page.description,
    isPublished: true, publishedAt: date,
  };
}
